            CODE('go env -w GOPROXY=https://' + HOST + '/repository/my-space/go/,https://proxy.golang.org,direct\ngo env -w GONOSUMDB=example.com/acme/*\n\n# ~/.netrc\nmachine ' + HOST + ' login me password <API token>'),
